/**
 * The course dictionary, generated by scripts/build-lexicon.ts from the lessons' word lists and
 * Wiktionary (via kaikki.org): every word the course teaches, plus every other word that appears
 * in its German text, with its gender, plural, principal parts and an English gloss.
 */
import LEXICON from '$content/data/lexicon.json';
import FORMS from '$content/data/forms.json';
import { annotate as annotateWith, type Dict, type Token } from './text';
import { pluralNotation, type Gender } from './notation';

export type Level = 'A1' | 'A2' | 'B1' | 'B2';
export const LEVELS: Level[] = ['A1', 'A2', 'B1', 'B2'];

export interface Entry {
  /** Part of speech: noun, verb, adjective/adverb, other (phrases, function words). */
  p: 'n' | 'v' | 'a' | 'x';
  /** English gloss. */
  g: string;
  /** Noun gender, or "pl" for plural-only nouns. */
  a?: Gender;
  /** Noun plural; null when the noun has no plural. */
  pl?: string | null;
  /** Genitive singular, when it is not the regular -(e)s (der Student → des Studenten). */
  gs?: string;
  /** Verb: third person present, preterite, past participle, auxiliary (h = haben, s = sein). */
  v?: [string, string, string, 'h' | 's' | 'hs'];
  /** Separable verb prefix. */
  sep?: string;
  /** Reflexive verb. */
  r?: 1;
  /** Comparative and superlative. */
  c?: [string, string];
  /** Level and lesson where the course teaches it (absent: met in text but not taught). */
  l?: Level;
  s?: string;
  /** Extra notation from the word list: "über + A", "+ D". */
  x?: string;
}

const LEX = LEXICON as unknown as Record<string, Entry>;
const FORM_MAP = FORMS as unknown as Record<string, string[]>;

export const dict: Dict = {
  forms: (s) => FORM_MAP[s] ?? (LEX[s] ? [s] : undefined),
  has: (k) => k in LEX,
  taughtNoun: (k) => LEX[k]?.p === 'n' && !!LEX[k]?.l,
};

export function lookup(key: string): Entry | undefined {
  return LEX[key];
}

export function allEntries(): [string, Entry][] {
  return Object.entries(LEX);
}

/** Words the course teaches, in lesson order within each level. */
export function taught(level?: Level): [string, Entry][] {
  return allEntries().filter(([, e]) => e.l && (!level || e.l === level));
}

export function annotate(text: string): Token[] {
  return annotateWith(text, dict);
}

/** The first entry for a word in running text (what its word card shows). */
export function entryFor(t: Token): [string, Entry] | undefined {
  for (const k of t.k ?? []) {
    const e = LEX[k];
    if (e) return [k, e];
  }
  return undefined;
}

/** The bare noun of a key: "der Tisch" → "Tisch". */
export const bare = (key: string) => key.replace(/#\d+$/, '').replace(/^(der|die|das|sich) /, '');

/** A key as written: homographs are stored as "sein#2". */
export const plainKey = (key: string) => key.replace(/#\d+$/, '');

/** How a dictionary entry is written in a word list: "die Stadt, ¨-e", "an|rufen", "fahren (fährt, fuhr, ist gefahren)". */
export function headword(key: string, e: Entry | undefined = LEX[key]): { head: string; extra: string } {
  if (!e) return { head: plainKey(key), extra: '' };
  if (key !== plainKey(key)) return headword(plainKey(key), e);
  if (e.p === 'n') {
    if (e.a === 'pl') return { head: key, extra: ' (Pl.)' };
    const noun = bare(key);
    const pl = e.pl === null ? 'Sg.' : e.pl ? pluralNotation(noun, e.pl) : '';
    return { head: key, extra: pl ? (pl === 'Sg.' ? ' (Sg.)' : `, ${pl}`) : '' };
  }
  if (e.p === 'v') {
    const refl = e.r ? 'sich ' : '';
    const inf = bare(key);
    const shown = e.sep && inf.startsWith(e.sep) ? `${e.sep}|${inf.slice(e.sep.length)}` : inf;
    const parts = e.v && isIrregular(inf, e) ? ` (${e.v[0]}, ${e.v[1]}, ${e.v[3] === 's' ? 'ist' : 'hat'} ${e.v[2]})` : '';
    return { head: `${refl}${shown}`, extra: `${parts}${e.x ? ` (${e.x})` : ''}` };
  }
  if (e.c && isIrregularComparison(key, e.c)) return { head: key, extra: ` (${e.c[0]}, ${e.c[1]})` };
  return { head: key, extra: e.x ? ` (${e.x})` : '' };
}

/** Regular (weak) verbs need no principal parts: machen → macht, machte, gemacht. */
export function isIrregular(inf: string, e: Entry): boolean {
  if (!e.v) return false;
  const stem = inf.replace(/^(.*?)(e?n)$/, '$1');
  const s = e.sep && stem.startsWith(e.sep) ? stem.slice(e.sep.length) : stem;
  const t = /[dt]$|[^aeioulrhä][mn]$/.test(s) ? `${s}et` : `${s}t`;
  const sepSuffix = e.sep ? ` ${e.sep}` : '';
  const pret = /[dt]$|[^aeioulrh][mn]$/.test(s) ? `${s}ete` : `${s}te`;
  return e.v[0] !== `${t}${sepSuffix}` || e.v[1] !== `${pret}${sepSuffix}` || e.v[3] === 's';
}

function isIrregularComparison(base: string, [cmp, sup]: [string, string]): boolean {
  return cmp !== `${base}er` || !(sup === `am ${base}sten` || sup === `am ${base}esten`);
}

export const GENDER_NAMES: Record<Gender, string> = { m: 'masculine', f: 'feminine', n: 'neuter', pl: 'plural' };

/** Common English words that are also German forms, so they do not count as German evidence. */
const SHARED = new Set(['die', 'also', 'will', 'war', 'hat', 'so', 'in', 'an', 'man', 'was', 'bad', 'kind', 'hell', 'gift', 'rat', 'fast', 'arm', 'hand', 'name', 'finger', 'land', 'wind', 'winter', 'warm', 'alt', 'see', 'note', 'rock', 'tag', 'bin', 'mist', 'fall', 'blind', 'elf', 'hut', 'rose', 'sale', 'taste', 'not', 'wild', 'wo', 'um', 'am', 'or', 'top', 'park', 'hotel', 'radio', 'taxi', 'bus', 'film', 'sport', 'ball', 'golf', 'tennis', 'pizza', 'tee', 'boot', 'lose']);

/**
 * Whether a string is German rather than English: most of its words are German forms the
 * course knows. Strings with {braces} are English with German inside.
 */
export function isGerman(s: string): boolean {
  if (/[{}]/.test(s)) return false;
  if (/[äöüßÄÖÜ]/.test(s)) return true;
  const words = annotate(s).filter((t) => t.w);
  if (!words.length) return false;
  const german = words.filter((t) => t.k?.length && !SHARED.has(t.t.toLowerCase())).length;
  const english = words.filter((t) => !t.k?.length).length;
  return german > 0 && german >= english;
}

/** The dictionary key of a bare noun: "Tisch" → "der Tisch" (taught entries first). */
export function nounKey(noun: string): string | undefined {
  const keys = [...(FORM_MAP[noun] ?? []), `der ${noun}`, `die ${noun}`, `das ${noun}`].filter((k) => LEX[k]?.p === 'n' && bare(k) === noun);
  return keys.find((k) => LEX[k]!.l) ?? keys[0];
}
